<template><div class="page-container"><PageHeader>设备管理</PageHeader><div class="filter-bar"><el-input v-model="keyword" placeholder="设备编码/名称" style="width:240px" @keyup.enter="load"/><el-button type="primary" @click="load">查询</el-button><el-button v-if="auth.isAdmin" type="success" @click="open()">新增设备</el-button></div><el-table :data="rows" border stripe><el-table-column prop="code" label="设备编码"/><el-table-column prop="name" label="设备名称"/><el-table-column prop="model" label="型号"/><el-table-column prop="location" label="安装位置"/><el-table-column prop="status" label="状态"/><el-table-column label="操作" width="160"><template #default="{row}"><el-button link type="primary" @click="showParts(row)">关联备件</el-button><el-button v-if="auth.isAdmin" link @click="open(row)">编辑</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.id?'编辑设备':'新增设备'" width="520px"><el-form label-width="90px"><el-form-item label="设备编码"><el-input v-model="form.code"/></el-form-item><el-form-item label="设备名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="型号"><el-input v-model="form.model"/></el-form-item><el-form-item label="安装位置"><el-input v-model="form.location"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option value="RUNNING" label="运行中"/><el-option value="STOPPED" label="停用"/><el-option value="MAINTENANCE" label="维护中"/></el-select></el-form-item><el-form-item label="制造商"><el-input v-model="form.manufacturer"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="partsVisible" :title="partEquipment?.name+' - 关联备件'" width="820px"><el-button v-if="auth.isAdmin" type="primary" size="small" @click="bindVisible=true">关联备件</el-button><el-table :data="partRows" border style="margin-top:12px"><el-table-column prop="sku" label="SKU"/><el-table-column prop="productName" label="备件"/><el-table-column prop="installedQty" label="单机数量"/><el-table-column prop="lifeCycleDays" label="预计寿命(天)"/><el-table-column prop="procurementLeadDays" label="采购周期(天)"/><el-table-column prop="nextExpectedUseDate" label="预计下次领用"/></el-table></el-dialog>
<el-dialog v-model="bindVisible" title="关联设备备件" width="500px"><el-form label-width="120px"><el-form-item label="备件"><el-select v-model="bind.productId" filterable style="width:100%"><el-option v-for="p in products" :key="p.id" :value="p.id" :label="p.sku+' - '+p.name"/></el-select></el-form-item><el-form-item label="单机数量"><el-input-number v-model="bind.installedQty" :min="1"/></el-form-item><el-form-item label="预计寿命(天)"><el-input-number v-model="bind.lifeCycleDays" :min="1"/></el-form-item><el-form-item label="消耗周期(天)"><el-input-number v-model="bind.consumptionCycleDays" :min="1"/></el-form-item><el-form-item label="采购周期(天)"><el-input-number v-model="bind.procurementLeadDays" :min="0"/></el-form-item><el-form-item label="安全库存"><el-input-number v-model="bind.safetyStock" :min="0"/></el-form-item></el-form><template #footer><el-button @click="bindVisible=false">取消</el-button><el-button type="primary" @click="saveBind">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,onMounted}from'vue';import PageHeader from '@/components/PageHeader.vue';import*as api from '@/api/equipment';import*as productsApi from '@/api/products';import{useAuthStore}from '@/stores/auth';const auth=useAuthStore(),keyword=ref(''),rows=ref([]),visible=ref(false),partsVisible=ref(false),bindVisible=ref(false),partRows=ref([]),products=ref([]),partEquipment=ref(),form=ref({}),bind=ref({installedQty:1,safetyStock:0});const load=async()=>rows.value=await api.list({keyword:keyword.value});function open(r){form.value=r?{...r}:{status:'RUNNING'};visible.value=true}async function save(){form.value.id?await api.update(form.value.id,form.value):await api.create(form.value);visible.value=false;load()}async function showParts(r){partEquipment.value=r;partRows.value=await api.parts(r.id);partsVisible.value=true;if(!products.value.length){const x=await productsApi.list({page:0,size:500});products.value=x.content||[]}}async function saveBind(){await api.bindPart(partEquipment.value.id,bind.value);bindVisible.value=false;bind.value={installedQty:1,safetyStock:0};partRows.value=await api.parts(partEquipment.value.id)}onMounted(load)</script>
